{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap for 2026","requirement":"A landlord may not charge a tenant screening fee above the state cap, must accept a reusable screening report, give a receipt and itemized costs, refund unused amounts, and return the fee to applicants not selected or when no unit is available.","key_value":"$68.96 per applicant for 2026","coverage_conditions":"Tenant screening fees charged to prospective tenants of residential rental units; the page states no building, unit or owner limits.","applicability":{"conditions":[],"per_tenancy":"Applies when an owner charges a screening fee to process a rental application.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026","valid_through":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and non-refundable application fee ban","requirement":"A Berkeley owner who charges a screening fee must give the applicant a tenant screening fee rights statement and the state fee cap, and may not charge an existing tenant a non-refundable fee to renew a tenancy or to add or replace a roommate.","key_value":null,"coverage_conditions":"Chapter 13.78 applies to all residential rental agreements regardless of any contractual language in any rental agreement or lease to the contrary.","applicability":{"conditions":[],"per_tenancy":"Applies when an owner charges a screening fee, or a renewal or roommate-change fee to an existing tenant.","coverage_quotes":[]},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the chapter is unenforceable.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
